shadow_bundle.shadow_css:
:host { display: block; width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }
.wsj-shadow-body { width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }

  :host {
    --paper: #faf8f4;
    --paper-card: #f3efe6;
    --paper-deep: #ebe5d8;
    --ink: #141413;
    --body: #242220;
    --muted: #646059;
    --line: #e4dfd3;
    --line-strong: #c9c1b0;
    --accent: #b85d19;
    --accent-soft: rgba(184, 93, 25, 0.13);
    --navy-bg: #0f1d2b;
    --navy-card: #16283a;
    --navy-line: #283f56;
    --font-serif-en: 'Playfair Display', Georgia, serif;
    --font-body-en: 'Lora', Georgia, serif;
    --font-serif-cn: 'Noto Serif SC', 'Songti SC', serif;
    --font-sans: 'Inter', 'Noto Sans SC', -apple-system, sans-serif;
    --font-mono: 'JetBrains Mono', monospace;
  }

  * {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
  }

  html {
    background-color: var(--paper);
    color: var(--body);
    scroll-behavior: smooth;
    -webkit-font-smoothing: antialiased;
  }

  :host([lang="zh-CN"]) .lang-en { display: none !important; }
  :host([lang="en"]) .lang-cn { display: none !important; }

  .wsj-shadow-body {
    font-family: var(--font-serif-cn);
    background-color: var(--paper);
    color: var(--body);
    line-height: 1.85;
    overflow-x: hidden;
  }

  :host([lang="en"]) .wsj-shadow-body {
    font-family: var(--font-body-en);
    line-height: 1.78;
  }

  /* Sticky Top Masthead */
  .masthead {
    position: sticky;
    top: 0;
    z-index: 1000;
    background: rgba(250, 248, 244, 0.94);
    backdrop-filter: blur(10px);
    border-bottom: 1px solid var(--line);
  }

  .masthead-inner {
    max-width: 1180px;
    margin: 0 auto;
    padding: 0.7rem 1.5rem;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
  }

  .brand-group {
    display: flex;
    align-items: center;
    gap: 0.85rem;
    flex-wrap: wrap;
  }

  .wsj-mark {
    font-family: var(--font-serif-en);
    font-weight: 800;
    font-size: 0.95rem;
    letter-spacing: 0.08em;
    color: var(--ink);
    text-transform: uppercase;
  }

  .brand-sep {
    width: 1px;
    height: 14px;
    background: var(--line-strong);
  }

  .section-tag {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--accent);
    font-weight: 600;
  }

  .lang-switch {
    display: inline-flex;
    align-items: center;
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    border-radius: 999px;
    padding: 2px;
  }

  .lang-btn {
    border: none;
    background: transparent;
    font-family: var(--font-mono);
    font-size: 0.74rem;
    font-weight: 600;
    padding: 0.3rem 0.75rem;
    border-radius: 999px;
    color: var(--muted);
    cursor: pointer;
    transition: all 0.2s ease;
  }

  :host([lang="zh-CN"]) .lang-btn[data-lang="zh-CN"],
  :host([lang="en"]) .lang-btn[data-lang="en"] {
    background: var(--ink);
    color: var(--paper);
  }

  .reading-progress {
    height: 2px;
    background: transparent;
    width: 100%;
    overflow: hidden;
  }

  .reading-progress-bar {
    height: 100%;
    width: 0%;
    background: var(--accent);
    transition: width 0.1s linear;
  }

  /* Hero Header */
  .hero {
    max-width: 1180px;
    margin: 0 auto;
    padding: 3.5rem 1.5rem 2.5rem;
    border-bottom: 1px solid var(--ink);
  }

  .hero-kicker {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    font-family: var(--font-mono);
    font-size: 0.76rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    color: var(--accent);
    margin-bottom: 1.25rem;
  }

  .hero-kicker::before {
    content: "";
    display: inline-block;
    width: 28px;
    height: 1px;
    background: var(--accent);
  }

  .hero-grid {
    display: grid;
    grid-template-columns: 1.35fr 0.65fr;
    gap: 3rem;
    align-items: end;
  }

  .article-title {
    font-family: var(--font-serif-cn);
    font-weight: 700;
    font-size: clamp(2.15rem, 4.2vw, 3.5rem);
    line-height: 1.22;
    color: var(--ink);
    letter-spacing: -0.01em;
    margin-bottom: 1.25rem;
  }

  :host([lang="en"]) .article-title {
    font-family: var(--font-serif-en);
    font-weight: 800;
    line-height: 1.12;
  }

  .article-dek {
    font-family: var(--font-sans);
    font-size: clamp(1.08rem, 1.6vw, 1.3rem);
    line-height: 1.6;
    color: var(--muted);
    font-weight: 400;
    max-width: 68ch;
  }

  .hero-meta-card {
    background: var(--paper-card);
    border: 1px solid var(--line);
    border-top: 3px solid var(--ink);
    padding: 1.35rem 1.5rem;
  }

  .meta-row {
    display: flex;
    justify-content: space-between;
    padding: 0.45rem 0;
    border-bottom: 1px dashed var(--line-strong);
    font-family: var(--font-mono);
    font-size: 0.76rem;
  }

  .meta-row:last-child {
    border-bottom: none;
    padding-bottom: 0;
  }

  .meta-label {
    color: var(--muted);
    text-transform: uppercase;
  }

  .meta-val {
    color: var(--ink);
    font-weight: 600;
    text-align: right;
  }

  /* Main Container */
  .page-container {
    max-width: 1180px;
    margin: 0 auto;
    padding: 0 1.5rem 5rem;
  }

  /* Editorial Two-Column Asymmetric Layout */
  .editorial-grid {
    display: grid;
    grid-template-columns: minmax(0, 680px) minmax(260px, 380px);
    justify-content: space-between;
    gap: 3.25rem;
    padding-top: 2.75rem;
  }

  /* Narrative Prose Styles */
  .prose-p {
    font-size: 1.125rem;
    color: var(--body);
    margin-bottom: 1.55rem;
    letter-spacing: 0.01em;
  }

  :host([lang="en"]) .prose-p {
    font-size: 1.14rem;
    letter-spacing: 0;
  }

  .lead-p {
    font-size: 1.26rem;
    line-height: 1.85;
    color: var(--ink);
    font-weight: 600;
    border-left: 3px solid var(--accent);
    padding-left: 1.2rem;
    margin-bottom: 1.85rem;
  }

  :host([lang="en"]) .lead-p {
    font-weight: 400;
    font-size: 1.28rem;
    line-height: 1.72;
  }

  mark.ed-hl {
    background: linear-gradient(180deg, transparent 58%, var(--accent-soft) 58%);
    color: inherit;
    padding: 0 0.12em;
    border-bottom: 1px solid rgba(184, 93, 25, 0.45);
  }

  /* Dictionary Lexicon Box (around p3) */
  .lexicon-card {
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    padding: 1.75rem 1.85rem;
    margin: 2rem 0;
    position: relative;
  }

  .lexicon-header {
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 0.5rem;
    border-bottom: 1px solid var(--line-strong);
    padding-bottom: 0.75rem;
    margin-bottom: 1rem;
  }

  .lexicon-term {
    font-family: var(--font-serif-en);
    font-size: 1.45rem;
    font-weight: 700;
    color: var(--ink);
  }

  .lexicon-phonetic {
    font-family: var(--font-mono);
    font-size: 0.78rem;
    color: var(--accent);
  }

  .lexicon-card .prose-p:last-child {
    margin-bottom: 0;
  }

  /* Saturday Creep Banner (p5) */
  .creep-callout {
    background: #f5efe3;
    border-left: 4px solid var(--ink);
    padding: 1.35rem 1.6rem;
    margin: 1.8rem 0 2.2rem;
  }

  .creep-kicker {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: var(--accent);
    margin-bottom: 0.45rem;
    font-weight: 700;
  }

  .creep-callout .prose-p {
    margin-bottom: 0;
    font-weight: 600;
    color: var(--ink);
  }

  /* Right Rail Cards */
  .side-rail {
    display: flex;
    flex-direction: column;
    gap: 2rem;
  }

  .rail-card {
    background: var(--paper-card);
    border: 1px solid var(--line);
    padding: 1.5rem;
  }

  .rail-card-title {
    font-family: var(--font-mono);
    font-size: 0.74rem;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: var(--accent);
    border-bottom: 1px solid var(--line-strong);
    padding-bottom: 0.6rem;
    margin-bottom: 1rem;
    font-weight: 700;
  }

  /* Pull Quote Styling */
  .pull-quote {
    background: var(--paper-card);
    border-top: 2px solid var(--ink);
    border-bottom: 1px solid var(--line-strong);
    padding: 1.5rem 1.4rem;
    margin: 0;
  }

  .pull-quote .quote-text {
    font-family: var(--font-serif-cn);
    font-size: 1.12rem;
    font-weight: 600;
    line-height: 1.65;
    color: var(--ink);
    margin-bottom: 0.75rem;
  }

  :host([lang="en"]) .pull-quote .quote-text {
    font-family: var(--font-serif-en);
    font-style: italic;
    font-weight: 700;
    font-size: 1.15rem;
  }

  .pull-quote .quote-attrib {
    font-family: var(--font-mono);
    font-size: 0.74rem;
    color: var(--muted);
    text-transform: uppercase;
    letter-spacing: 0.06em;
  }

  /* Section Divider */
  .chapter-break {
    margin: 3.5rem 0 2.5rem;
    border-top: 1px solid var(--ink);
    padding-top: 1rem;
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    gap: 1rem;
    flex-wrap: wrap;
  }

  .chapter-num {
    font-family: var(--font-mono);
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    color: var(--accent);
    font-weight: 700;
  }

  .chapter-heading {
    font-family: var(--font-serif-cn);
    font-size: 1.55rem;
    font-weight: 700;
    color: var(--ink);
  }

  :host([lang="en"]) .chapter-heading {
    font-family: var(--font-serif-en);
  }

  /* ActivTrak Data Feature Band (Navy Dark Dossier) */
  .data-feature-band {
    background: var(--navy-bg);
    color: #f4f1ea;
    padding: 2.75rem 2.25rem;
    margin: 2.5rem 0;
    border-radius: 2px;
    border-top: 4px solid var(--accent);
  }

  .data-feature-grid {
    display: grid;
    grid-template-columns: 1.1fr 0.9fr;
    gap: 2.5rem;
    align-items: center;
  }

  .data-feature-band .prose-p {
    color: #e9e4d8;
    font-size: 1.15rem;
    margin-bottom: 1.35rem;
  }

  .data-feature-band mark.ed-hl {
    background: rgba(184, 93, 25, 0.35);
    border-bottom-color: #f09549;
    color: #fff;
  }

  .metric-card {
    background: var(--navy-card);
    border: 1px solid var(--navy-line);
    padding: 1.35rem 1.5rem;
    margin-top: 1rem;
  }

  .metric-val {
    font-family: var(--font-mono);
    font-size: 2.6rem;
    font-weight: 700;
    color: #f29a4b;
    line-height: 1.1;
    margin-bottom: 0.35rem;
  }

  .metric-lbl {
    font-family: var(--font-sans);
    font-size: 0.9rem;
    font-weight: 600;
    color: #ffffff;
    margin-bottom: 0.3rem;
  }

  .metric-note {
    font-family: var(--font-sans);
    font-size: 0.78rem;
    color: #a7b6c5;
    line-height: 1.45;
  }

  /* Case Dossier Header Tags for p9, p10, p11 */
  .persona-block {
    border-top: 1px solid var(--line-strong);
    padding-top: 1.5rem;
    margin-top: 1.75rem;
  }

  .persona-tag {
    display: inline-flex;
    align-items: center;
    gap: 0.5rem;
    font-family: var(--font-mono);
    font-size: 0.73rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--accent);
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    padding: 0.25rem 0.65rem;
    margin-bottom: 0.95rem;
    font-weight: 600;
  }

  /* Clinical & Psychological Prescriptions (p12-p14) */
  .prescription-card {
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    padding: 1.6rem 1.75rem;
    margin-bottom: 1.5rem;
  }

  .rx-badge {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: var(--ink);
    font-weight: 700;
    margin-bottom: 0.65rem;
    display: flex;
    align-items: center;
    gap: 0.5rem;
  }

  .rx-badge span.rx-num {
    background: var(--ink);
    color: var(--paper);
    padding: 0.1rem 0.45rem;
    font-size: 0.68rem;
  }

  .prescription-card .prose-p {
    margin-bottom: 0;
  }

  /* Climactic Finale Box (p14) */
  .rebrand-finale {
    background: linear-gradient(135deg, #f3efe6 0%, #ebe3d2 100%);
    border: 1px solid var(--ink);
    padding: 2.2rem 2.25rem;
    margin-top: 2rem;
  }

  .rebrand-comparison {
    display: flex;
    align-items: center;
    gap: 1rem;
    flex-wrap: wrap;
    margin-bottom: 1.25rem;
    padding-bottom: 1rem;
    border-bottom: 1px dashed var(--line-strong);
    font-family: var(--font-mono);
    font-size: 0.82rem;
  }

  .term-old {
    text-decoration: line-through;
    color: var(--muted);
  }

  .term-arrow {
    color: var(--accent);
    font-weight: 700;
  }

  .term-new {
    background: var(--ink);
    color: var(--paper);
    padding: 0.2rem 0.65rem;
    font-weight: 700;
  }

  .verdict-quote {
    margin-top: 1.25rem;
    padding-left: 1.15rem;
    border-left: 3px solid var(--accent);
    font-family: var(--font-serif-cn);
    font-size: 1.22rem;
    font-weight: 700;
    color: var(--ink);
    line-height: 1.65;
  }

  :host([lang="en"]) .verdict-quote {
    font-family: var(--font-serif-en);
    font-style: italic;
  }

  /* Reporter Context Footer Dossier */
  .context-dossier {
    margin-top: 4rem;
    background: var(--paper-card);
    border-top: 3px solid var(--ink);
    border-bottom: 1px solid var(--line-strong);
    padding: 2rem 2.25rem;
  }

  .context-label {
    font-family: var(--font-mono);
    font-size: 0.75rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: var(--accent);
    margin-bottom: 0.75rem;
    font-weight: 700;
  }

  .context-dossier .prose-p {
    font-family: var(--font-sans);
    font-size: 0.96rem;
    color: var(--muted);
    margin-bottom: 0;
    line-height: 1.75;
  }

  .colophon {
    margin-top: 3rem;
    padding-top: 1.5rem;
    border-top: 1px solid var(--line);
    display: flex;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 1rem;
    font-family: var(--font-mono);
    font-size: 0.74rem;
    color: var(--muted);
  }

  /* Responsive Mobile Reflow */
  @media (max-width: 920px) {
    .hero-grid,
    .editorial-grid,
    .data-feature-grid {
      grid-template-columns: 1fr;
      gap: 2rem;
    }

    .hero {
      padding: 2.25rem 1.15rem 1.75rem;
    }

    .page-container {
      padding: 0 1.15rem 3.5rem;
    }

    .data-feature-band {
      padding: 1.85rem 1.25rem;
    }

    .rebrand-finale,
    .lexicon-card,
    .context-dossier {
      padding: 1.4rem 1.25rem;
    }
  }
